import{_ as t,o as i,c as o,a5 as a}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"3.2.1 Sign Up (Email + OTP Verification)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-1-sign-up/spec.md","filePath":"feature/authentication/3-2-1-sign-up/spec.md"}'),s={name:"feature/authentication/3-2-1-sign-up/spec.md"};function n(r,e,l,d,c,u){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="_3-2-1-sign-up-email-otp-verification" tabindex="-1">3.2.1 Sign Up (Email + OTP Verification) <a class="header-anchor" href="#_3-2-1-sign-up-email-otp-verification" aria-label="Permalink to &quot;3.2.1 Sign Up (Email + OTP Verification)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.2.1</td></tr><tr><td>Feature</td><td>Sign Up</td></tr><tr><td>Domain</td><td>Authentication (FR 3.2)</td></tr><tr><td>Role</td><td>GUEST (unauthenticated)</td></tr><tr><td>Version</td><td>2.0 — 2026-09-25 — rewritten against real code (register, verify-otp, resend-otp)</td></tr><tr><td>Document status</td><td>Implemented</td></tr></tbody></table><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>Begins when an unauthenticated Guest opens the Sign Up screen and submits Full Name, Email and Password; continues through the OTP Verification screen, which submits the 6-digit code and can trigger a Resend.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> GUEST. Creates a new account with the default system role USER.</li><li><strong>Purpose:</strong> Register a new account, prove ownership of the email address with a one-time code (OTP), and hand the user to Sign In. No session is created by this FR.</li><li><strong>Interface:</strong><ul><li>Registration form: Full Name, Email, Password (with strength meter), Confirm Password (client-side only).</li><li>OTP Verification screen: 6 single-digit inputs, Verify button, Resend link with cooldown countdown.</li></ul></li><li><strong>Data Processing:</strong> <code>AuthController.register</code> → <code>AuthServiceImpl.register</code> normalizes the email (lowercase + trim), BCrypt-hashes the password, generates a 6-digit numeric OTP (100000–999999) with a 10-minute expiry, persists the User row, assigns <code>UserSystemRole(SystemRole.USER)</code>, and sends the OTP email. <code>verifyOtp</code> and <code>resendOtp</code> are handled by the same controller/service and are part of this FR&#39;s completion flow.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Sign Up Screen:</p><ul><li>Full Name input, Email input, Password input (show/hide toggle + real-time strength meter: min 8 chars, at least 1 digit), Confirm Password input (client-side match check only, never sent to the server).</li><li>Submit button (&quot;Create account&quot;); tab toggle to switch to the Sign In screen; Google OAuth button; footer link to Sign In.</li><li>On success, the app toasts MSG10 and navigates to <code>/verify-otp?email=&lt;email&gt;</code>.</li></ul><p>Figure — OTP Verification Screen:</p><ul><li>Six single-digit numeric inputs (auto-advance on entry, backspace/arrow navigation, paste support), Verify button (disabled until all 6 digits entered).</li><li>&quot;Didn&#39;t receive a code? Resend&quot; link, disabled while a resend cooldown is active (countdown in seconds) or while a resend request is in flight.</li><li>Back-to-Sign-In link.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required (register):</strong> email, password, fullName — <code>RegisterRequest{email, password, fullName}</code>.</li><li><strong>Input required (verify-otp):</strong> email, otpCode — <code>VerifyOtpRequest{email, otpCode}</code>.</li><li><strong>Input required (resend-otp):</strong> email — reuses <code>ForgotPasswordRequest{email}</code> (only its <code>email</code> field is used).</li><li><strong>Input optional:</strong> confirmPassword is verified client-side only and is never submitted to the API.</li><li><strong>System data:</strong> userId, systemRole (USER), passwordHash (BCrypt), otpCode, otpExpiry, emailVerifiedAt, Redis keys <code>otp:attempt:&lt;email&gt;</code> (failed-attempt counter, TTL 10 min) and <code>otp:resend:&lt;email&gt;</code> (resend cooldown, TTL 60s).</li><li><strong>Output (register):</strong> <code>RegisterResponse{userId}</code> — no email/otpSessionId is returned.</li><li><strong>Output (verify-otp / resend-otp):</strong> <code>ApiResponse&lt;Void&gt;</code> — no payload body.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-01:</strong> Email is unique and compared case-insensitively; the service always lowercases + trims before storing and before the uniqueness check (<code>User@x.com</code> and <code>user@x.com</code> collide). A duplicate → <code>DataIntegrityViolationException</code> → 409 <code>EMAIL_ALREADY_EXISTS</code>.</li><li><strong>BR-02:</strong> Password policy — minimum 8 characters, at least 1 digit (enforced by request validation, <code>VALIDATION_ERROR</code> on failure); hashed with BCrypt cost 12; the plaintext password is never logged, stored, or returned.</li><li><strong>BR-03:</strong> Email OTP is 6 digits (numeric, 100000–999999), TTL 10 minutes, single-use — cleared (<code>otpCode</code>/<code>otpExpiry</code> set to null) as soon as it is consumed successfully or after 5 failed attempts.</li><li><strong>BR-04:</strong> Resend OTP has a 60-second cooldown per email, enforced via the Redis key <code>otp:resend:&lt;email&gt;</code> (<code>SETEX ... 60</code>). A resend request while the key still exists → 429 <code>RATE_LIMIT_EXCEEDED</code>.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>email, fullName, or password empty → Display: MSG02.</li><li>email invalid format → Display: MSG04.</li><li>password fewer than 8 characters or missing a digit → Display: MSG05.</li><li>confirmPassword mismatch (client-side only) → Display: MSG06.</li><li>duplicate email on register → Display: MSG08 (toast), HTTP 409 <code>EMAIL_ALREADY_EXISTS</code>.</li><li>OTP wrong or expired → Display: MSG20 (inline on the OTP screen), HTTP 400 <code>OTP_INVALID</code>.</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow-—-register" tabindex="-1">Normal Flow — Register <a class="header-anchor" href="#normal-flow-—-register" aria-label="Permalink to &quot;Normal Flow — Register&quot;">​</a></h3><ol><li>Guest opens the Sign Up screen and fills in Full Name, Email, Password, Confirm Password.</li><li>Client validates fields locally (required, email format, password policy, confirm match) and submits <code>{email, password, fullName}</code> to <code>POST /api/v1/auth/register</code>.</li><li><code>AuthServiceImpl.register</code>: lowercases+trims the email, BCrypt-hashes the password, trims fullName, generates a 6-digit OTP with a 10-minute expiry, saves the User, saves <code>UserSystemRole(USER)</code>, sends the OTP email.</li><li>On success: 201 CREATED, body <code>RegisterResponse{userId}</code>. Toast MSG10 (&quot;Account created. A verification code has been sent to {email_address}.&quot;). Client navigates to <code>/verify-otp?email=&lt;email&gt;</code>.</li></ol><h3 id="normal-flow-—-verify-otp" tabindex="-1">Normal Flow — Verify OTP <a class="header-anchor" href="#normal-flow-—-verify-otp" aria-label="Permalink to &quot;Normal Flow — Verify OTP&quot;">​</a></h3><ol><li>Guest enters the 6-digit code on the OTP Verification screen and submits <code>{email, otpCode}</code> to <code>POST /api/v1/auth/verify-otp</code>.</li><li><code>AuthServiceImpl.verifyOtp</code>: looks up the user by (normalized) email; if the code matches and has not expired, clears the Redis attempt counter, clears <code>otpCode</code>/<code>otpExpiry</code>, and sets <code>emailVerifiedAt = now</code>.</li><li>On success: 200, <code>ApiResponse&lt;Void&gt;</code>. Client toasts success and navigates to <code>/login</code>. No session/token is issued — the user signs in separately.</li></ol><h3 id="normal-flow-—-resend-otp" tabindex="-1">Normal Flow — Resend OTP <a class="header-anchor" href="#normal-flow-—-resend-otp" aria-label="Permalink to &quot;Normal Flow — Resend OTP&quot;">​</a></h3><ol><li>Guest clicks Resend on the OTP Verification screen; client submits <code>{email}</code> to <code>POST /api/v1/auth/resend-otp</code>.</li><li><code>AuthServiceImpl.resendOtp</code>: checks the Redis cooldown key; if absent, looks up the user, generates a new OTP + 10-minute expiry, saves it, sets the 60-second cooldown key, clears the attempt counter, and sends the new OTP email.</li><li>On success: 200, <code>ApiResponse&lt;Void&gt;</code>. Toast MSG21. Client starts a 60-second cooldown on the Resend link.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>2.a1: Email already registered (case-insensitive, BR-01) → 409 <code>EMAIL_ALREADY_EXISTS</code>, toast MSG08. 2.a2: The existing account is not modified; no OTP is re-sent automatically; the Guest switches to Sign In or requests Resend after verifying identity separately.</li><li>2.b1: email/fullName/password fails validation (BR-02) → 400 <code>VALIDATION_ERROR</code>, Display MSG02/MSG04/MSG05 under the offending field. 2.b2: Guest corrects the field and resubmits.</li><li>V.a1: <code>verifyOtp</code> called with an email that has no account → 404 <code>USER_NOT_FOUND</code>.</li><li>V.b1: User&#39;s email is already verified → idempotent 200 no-op (no error, no OTP re-check) — repeated verification calls are safe.</li><li>V.c1: <code>otpExpiry</code>/<code>otpCode</code> is null, or the code has expired → 400 <code>OTP_INVALID</code>, Display MSG20.</li><li>V.d1: Submitted code does not match → increments the Redis attempt counter (<code>otp:attempt:&lt;email&gt;</code>, TTL 10 min); if attempts &lt; 5 → 400 <code>OTP_INVALID</code>, Display MSG20. V.d2: On the 5th failed attempt → the OTP fields are cleared and the attempt key deleted → 400 <code>OTP_TOO_MANY_ATTEMPTS</code>; the Guest must use Resend to get a new code.</li><li>R.a1: Resend requested within 60 seconds of the previous resend → 429 <code>RATE_LIMIT_EXCEEDED</code>, toast MSG88.</li><li>R.b1: Resend requested for an email with no account → 404 <code>USER_NOT_FOUND</code>.</li><li>R.c1: Resend requested for an already-verified email → idempotent 200 no-op; no new OTP is generated or sent.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>After register: a User row exists with the default role USER, <code>emailVerifiedAt</code> null, a pending OTP (6 digits, 10-minute TTL) stored, and the OTP email sent. No session is established.</li><li>After a successful verify-otp: <code>emailVerifiedAt</code> is set, <code>otpCode</code>/<code>otpExpiry</code> are cleared, and the Redis attempt counter for that email is deleted. The user is not signed in; sign-in is a separate step.</li><li>After a successful resend-otp: a new OTP + 10-minute expiry replaces the previous one, the 60-second Redis cooldown key is set, and the previous attempt counter is cleared.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Sign In (separate FR) — verification does not issue any token.</li><li>OAuth-based sign-up (Google button shown on the screen but out of scope for this FR).</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><p>Ground truth: <code>AuthController.java</code>, <code>AuthServiceImpl.java</code> (<code>register</code>, <code>verifyOtp</code>, <code>resendOtp</code>, <code>generateOtp</code>), <code>ErrorCode.java</code>. BA: Section5_Requirement_Appendix.md (BR-01..BR-04, MSG02/04/05/06/08/10/20/21/88) — read-only, not modified.</p>',33)])])}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
